70	export const MANAGED_HOST_RUN_SCHEMA_VERSION = 'lattice.managed_host_run.v1' as const;
71	export const MANAGED_HOST_RUN_STATUS_WAIT_MAX_MS = 30_000;
72	export const MANAGED_HOST_RUN_DEFAULT_DEADLINE_MS = 30 * 60 * 1000;
73	export const MANAGED_HOST_RUN_MAX_DEADLINE_MS = 24 * 60 * 60 * 1000;
74	export const MANAGED_HOST_RUN_CLAIM_TIMEOUT_MS = 5_000;
75	export const MANAGED_HOST_RUN_TERMINAL_RETENTION_MS = 90 * 24 * 60 * 60 * 1000;
