79	export type ManagedHostRunState =
80	  | 'submitted'
81	  | 'running'
82	  | 'completed'
83	  | 'failed'
84	  | 'cancelled'
85	  | 'timed_out';
86	
87	export type ManagedHostRunTerminalState = Extract<
88	  ManagedHostRunState,
89	  'completed' | 'failed' | 'cancelled' | 'timed_out'
90	>;
91	
92	interface ManagedHostRunCancellationTerminal {
93	  state: Extract<ManagedHostRunTerminalState, 'cancelled' | 'timed_out'>;
94	  reason: string;
95	}
96	
97	function classifyManagedHostRunCancellation(reason: string): ManagedHostRunCancellationTerminal {
98	  return reason === 'absolute_deadline_exceeded'
99	    ? { state: 'timed_out', reason: 'absolute_deadline_exceeded' }
100	    : { state: 'cancelled', reason };
101	}
