527	/**
528	 * Remove only the detached cross-host snapshot shape created by the managed
529	 * adapter. The canonical tmp boundary is checked before either git metadata or
530	 * filesystem state is touched, so a persisted caller-controlled cwd cannot
531	 * turn retention GC into an arbitrary deletion primitive.
532	 */
533	export function cleanupManagedCrossHostReviewWorktree(gitCwd: string, worktree: string): void {
534	  const parent = dirname(worktree);
535	  if (basename(worktree) !== 'worktree'
536	    || !basename(parent).startsWith('lattice-xhr-review-')
537	    || dirname(parent) !== tmpdir()) {
538	    throw new Error(`managed host run: cross-host review snapshot is outside the canonical temporary boundary: ${worktree}`);
539	  }
540	  if (!existsSync(worktree)) {
541	    const registeredWorktrees = execFileSync('git', ['worktree', 'list', '--porcelain'], {
542	      cwd: gitCwd,
543	      encoding: 'utf8',
544	      stdio: ['ignore', 'pipe', 'pipe'],
545	      maxBuffer: 8 * 1024 * 1024,
546	    });
547	    const registered = registeredWorktrees
548	      .split('\n')
549	      .some(line => line === `worktree ${resolve(worktree)}`);
550	    if (!registered) {
551	      rmSync(parent, { recursive: true, force: true });
552	      return;
553	    }
554	  }
555	  // Git administration is authoritative for a registered worktree. If this
556	  // mutation fails, retain the filesystem snapshot and surface the error to GC
557	  // diagnostics; deleting only the directory would strand hidden registration
558	  // state while falsely reporting successful cleanup.
559	  execFileSync('git', ['worktree', 'remove', '--force', worktree], {
560	    cwd: gitCwd,
561	    encoding: 'utf8',
562	    stdio: ['ignore', 'pipe', 'pipe'],
563	    maxBuffer: 8 * 1024 * 1024,
564	  });
565	  rmSync(parent, { recursive: true, force: true });
566	}
