596	async function withManagedReconcileLock<T>(
597	  paths: ManagedHostRunPaths,
598	  fn: () => Promise<T>,
599	): Promise<T> {
600	  const previous = managedReconcileQueues.get(paths.reconcileLock) ?? Promise.resolve();
601	  let releaseTurn!: () => void;
602	  const turn = new Promise<void>(resolve => { releaseTurn = resolve; });
603	  const tail = previous.then(() => turn);
604	  managedReconcileQueues.set(paths.reconcileLock, tail);
605	  await previous;
606	  let lock: ReturnType<typeof acquireMkdirLock> | null = null;
607	  try {
608	    lock = acquireMkdirLock(paths.reconcileLock, {
609	      label: `managed reconcile ${paths.dir}`,
610	      deadlineMs: 5_000,
611	      staleMs: 2_000,
612	      pollMs: 10,
613	      requireHolderToken: true,
614	      classifyExistingLock: classifyManagedHostRunTerminalLock,
615	      holderInfo: {
616	        pid: process.pid,
617	        hostname: hostname(),
618	        command: `managed reconcile ${paths.dir}`,
619	        acquiredAt: new Date().toISOString(),
620	        lockId: randomUUID(),
621	        processStartTimeMs: currentProcessStartTimeMs(),
622	      },
623	    });
624	    return await fn();
625	  } finally {
626	    lock?.release();
627	    releaseTurn();
628	    if (managedReconcileQueues.get(paths.reconcileLock) === tail) {
629	      managedReconcileQueues.delete(paths.reconcileLock);
630	    }
631	  }
632	}
