641	    const buffer = Buffer.allocUnsafe(maxBytes + 1);
642	    const bytesRead = readSync(fd, buffer, 0, buffer.length, 0);
643	    return {
644	      text: buffer.subarray(0, Math.min(bytesRead, maxBytes)).toString('utf8'),
645	      truncated: bytesRead > maxBytes,
