760	        || typeof binding.reviewRunId !== 'string'
761	        || typeof binding.lane !== 'string'
762	        || typeof binding.importedAt !== 'string'
763	        || !Array.isArray(binding.importedIds)
764	        || binding.importedIds.length === 0
765	        || binding.importedIds.some(value => typeof value !== 'string' || value.length === 0)
